// Design tokens. Mirrors SYSTEM RULES/01_SYSTEM_GLOBAL_DESIGN_TOKENS.md.
// Shipped as a string so preview and export share one stylesheet byte for byte.
// Gilroy ships as five real weights (Regular/Medium/SemiBold/Bold/ExtraBold, each with an
// italic) rather than one weight faked bold/light by the browser — every font-weight
// already used across the section files (400/500/600/700/800) lands on its own real cut.
const FONT_FACES = `
@font-face{font-family:'Gilroy';font-weight:400;font-style:normal;font-display:swap;src:url(data:font/ttf;base64,) format('truetype')}
@font-face{font-family:'Gilroy';font-weight:400;font-style:italic;font-display:swap;src:url(data:font/ttf;base64,) format('truetype')}
@font-face{font-family:'Gilroy';font-weight:500;font-style:normal;font-display:swap;src:url(data:font/ttf;base64,) format('truetype')}
@font-face{font-family:'Gilroy';font-weight:500;font-style:italic;font-display:swap;src:url(data:font/ttf;base64,) format('truetype')}
@font-face{font-family:'Gilroy';font-weight:600;font-style:normal;font-display:swap;src:url(data:font/ttf;base64,) format('truetype')}
@font-face{font-family:'Gilroy';font-weight:600;font-style:italic;font-display:swap;src:url(data:font/ttf;base64,) format('truetype')}
@font-face{font-family:'Gilroy';font-weight:700;font-style:normal;font-display:swap;src:url(data:font/ttf;base64,) format('truetype')}
@font-face{font-family:'Gilroy';font-weight:700;font-style:italic;font-display:swap;src:url(data:font/ttf;base64,) format('truetype')}
@font-face{font-family:'Gilroy';font-weight:800;font-style:normal;font-display:swap;src:url(data:font/ttf;base64,) format('truetype')}
@font-face{font-family:'Gilroy';font-weight:800;font-style:italic;font-display:swap;src:url(data:font/ttf;base64,) format('truetype')}
`;

export const TOKENS_CSS = `
${FONT_FACES}
:root{
  /* backgrounds — SYS-01 §2 */
  --bg-white:#FFFFFF;
  --bg-light-grey:rgba(0,0,0,.04);
  --bg-light-bronze:#F7F2EE;

  /* ink and accent */
  --ink:rgba(0,0,0,.88);
  --ink-soft:rgba(0,0,0,.62);
  --ink-faint:rgba(0,0,0,.42);
  --bronze:#B8876E;
  --line:rgba(0,0,0,.12);
  --on-dark:#FFFFFF;

  --font:'Gilroy',-apple-system,BlinkMacSystemFont,"Segoe UI",Inter,Roboto,Helvetica,Arial,sans-serif;

  /* Type scale — SYS-01 §3.1. Five roles, each with one weight and (except Display) a
     Large/Medium/Small size — the same shape as Material's or Apple's type systems, sized to
     this app's own proportions rather than copied from theirs.
     Display   — not a heading size of its own: the emphasis weight for text the admin bolds
                 *inside* an already-bold heading (the hero H1), where the default bold step
                 would be invisible against a heading that starts at Headline weight already.
     Headline  — every dynamic section's own H2 (the existing S/M/L heading_size field), and
                 the hero H1's own base weight.
     Title     — names one step down: card/item/row titles, person names.
     Body      — running copy: paragraphs, descriptions, list text.
     Label     — small supporting text: eyebrows, badges, captions, nav. */
  --display-weight:800;

  --headline-l:40px; --headline-m:32px; --headline-s:24px;
  --headline-l-mobile:28px; --headline-m-mobile:24px; --headline-s-mobile:20px;
  --headline-weight:700;
  /* kept as aliases: every existing --h-* reference still resolves */
  --h-l:var(--headline-l); --h-m:var(--headline-m); --h-s:var(--headline-s);
  --h-l-mobile:var(--headline-l-mobile); --h-m-mobile:var(--headline-m-mobile); --h-s-mobile:var(--headline-s-mobile);
  --h-weight:var(--headline-weight);

  --title-l:20px; --title-m:18px; --title-s:16px;
  --title-weight:600;

  --body-l:16px; --body-m:14px; --body-s:12px;
  --body-weight:500;

  --label-l:14px; --label-m:13px; --label-s:12px;
  --label-weight:600;

  /* geometry */
  --container:1180px;
  --gutter:24px;
  --section-y:72px;
  --radius:10px;
  --radius-sm:8px;
  --radius-pill:999px;

  --header-offset:24px;
}
@media (max-width:767px){
  :root{ --section-y:48px; --gutter:20px; }
}
`;
